 return { id: lesson.id, title: lesson.title, status: lesson.id <= completed? 'completed' : 'current' };
});
console.log('\nmap - cards:', cards);

// filter - keep matching elements
let completedLessons = lessons.filter(lesson => lesson.status === 'completed');
console.log('\nfilter - completed lessons:', completedLessons.map(l => l.title)); // ['Intro', 'Variables']

let completedById = lessons.filter(lesson => lesson.id <= completed);
console.log('filter - by id <= completed:', completedById.map(l => l.title)); // ['Intro', 'Variables']

// find - first matching element
let lesson3 = lessons.find(lesson => lesson.id === 3);
