let currentLesson = lessons.find(lesson => lesson.status === 'current');
console.log('find - current lesson:', currentLesson.title); // Operators

let notFound = lessons.find(lesson => lesson.id === 10);
console.log('find - not found id 10:', notFound); // undefined

// Your dashboard could use filter to count completed
let completedCount = lessons.filter(l => l.status === 'completed').length;
console.log(`\nCompleted count with filter: ${completedCount}`); // 2

