console.log('\nSome locked?', hasLocked); // true - at least one locked

let hasCurrent = lessons.some(lesson => lesson.status === 'current');
console.log('Some current?', hasCurrent); // true

let hasAllCompleted = lessons.some(lesson => lesson.status === 'completed' && lesson.id === 10);
console.log('Some completed id 10?', hasAllCompleted); // false

// every - all pass
let allCompleted = lessons.every(lesson => lesson.status === 'completed');
console.log('\nEvery completed?', allCompleted); // false - not all completed

let allHaveId = lessons.every(lesson => lesson.id > 0);
console.log('Every has id >0?', allHaveId); // true - all have id >0

// Your dashboard - check if course completed
let completed = 2;
let allDone = lessons.every(lesson => lesson.id <= completed);
console.log(`\nCourse completed with completed=${completed}?`, allDone); // false - not all <=2

let completedAll = 4;
let allDone2 = lessons.every(lesson => lesson.id <= completedAll);
console.log(`Course completed with completed=${completedAll}?`, allDone2); // true - all 4 <=4

// Chain - total XP of completed lessons only
let completedXP = lessons.filter(l => l.status === 'completed').reduce((total, l) => total + l.xp, 0);
console.log(`\nCompleted XP with filter+reduce: ${completedXP}`); // 200

let user = { xp: 120, coins: 30, completed: 2, name: "Prince" };
let lessons = [{id: 1, title: 'Intro'}, {id: 2, title: 'Variables'}, {id: 3, title: 'Operators'}];

// Destructuring object - extract properties
console.log('Without destructuring - 3 lines:');
let xp1 = user.xp;
let coins1 = user.coins;
let completed1 = user.completed;
console.log(xp1, coins1, completed1);

console.log('\nWith destructuring - 1 line:');
let { xp, coins, completed } = user; // Extract xp, coins, completed from user
console.log(xp, coins, completed); // 120 30 2

// Destructuring with rename
let { xp: userXP, name: userName } = user;
