// Destructuring array
let [first, second, third] = lessons;
console.log('\nArray destructuring:');
console.log('First:', first.title); // Intro
console.log('Second:', second.title); // Variables
console.log('Third:', third.title); // Operators

// Destructuring with rest
let [firstLesson,...restLessons] = lessons;
console.log('\nFirst:', firstLesson.title); // Intro
console.log('Rest:', restLessons.map(l => l.title)); // [Variables, Operators]

// Spread - copy array
let lessonsCopy = [...lessons]; // Copy all lessons
console.log('\nSpread copy:', lessonsCopy.map(l => l.title)); // Same as lessons

// Spread - add new lesson
let newLessons = [...lessons, {id: 4, title: 'Conditions'}];
console.log('Spread add:', newLessons.map(l => l.title)); // Intro, Variables, Operators, Conditions
console.log('Original still:', lessons.map(l => l.title)); // Original unchanged - immutable

// Spread - copy object and overwrite
let updatedUser = {...user, xp: 170, coins: 40 }; // Copy user, overwrite xp and coins
