console.log(`\nTotal XP of all lessons: ${totalXP}`);

// Filter completed lessons - array methods
let completedLessons = lessons.filter(lesson => lesson.id <= completed);
console.log(`Completed lessons: ${completedLessons.map(l => l.title).join(', ')}`);

// Find current lesson
let currentLesson = lessons.find(lesson => lesson.id === completed + 1);
console.log(`Current lesson: ${currentLesson.title}`);

