console.log(`\nJS progress via variable key [COURSE_ID]: ${jsProgress}`);

let lessons = [
 {id: 1, title: 'Intro', status: 'completed', xp: 100},
 {id: 2, title: 'Variables', status: 'completed', xp: 100},
 {id: 3, title: 'Operators', status: 'current', xp: 0},
 {id: 4, title: 'Conditions', status: 'locked', xp: 0},
