];

// map - get all titles
let titles = lessons.map(l => l.title);
console.log('All titles:', titles);

// filter - completed only
let completedLessons = lessons.filter(l => l.status === 'completed');
console.log('\nCompleted:', completedLessons.map(l => l.title)); // Intro, Variables

// filter + map chain - titles of completed
let completedTitles = lessons.filter(l => l.status === 'completed').map(l => l.title);
console.log('Completed titles chain:', completedTitles);

// find - current lesson
let current = lessons.find(l => l.status === 'current');
console.log('\nCurrent lesson:', current.title); // Operators

