/* =========================================================
 COMPLETE ARRAYS AND OBJECTS DASHBOARD - Lesson 7 Capstone
 Uses: Array, Object, map, filter, find, reduce, destructuring, spread,?.,??
========================================================= */

const TOTAL_LESSONS = 10;
let lessons = [
 {id: 1, title: 'Introduction to JavaScript', learn: 'Understand JS', summary: 'Learn syntax', status: 'completed', xp: 100, coins: 10},
 {id: 2, title: 'Variables and Data Types', learn: 'Store info', summary: 'Learn let, const', status: 'completed', xp: 100, coins: 10},
 {id: 3, title: 'Operators', learn: 'Math and logic', summary: 'Master operators', status: 'current', xp: 0, coins: 0},
 {id: 4, title: 'Conditions', learn: 'Decisions', summary: 'Learn if/else', status: 'locked', xp: 0, coins: 0},
 {id: 5, title: 'Loops', learn: 'Repetition', summary: 'Learn for, while', status: 'locked', xp: 0, coins: 0},
 {id: 6, title: 'Functions', learn: 'Reusable blocks', summary: 'Learn functions', status: 'locked', xp: 0, coins: 0},
 {id: 7, title: 'Arrays and Objects', learn: 'Collections', summary: 'Learn arrays, objects', status: 'locked', xp: 0, coins: 0},
 {id: 8, title: 'DOM Manipulation', learn: 'Control HTML', summary: 'Learn DOM', status: 'locked', xp: 0, coins: 0},
 {id: 9, title: 'Events and Modern JS', learn: 'Interactivity', summary: 'Learn events', status: 'locked', xp: 0, coins: 0},
 {id: 10, title: 'Build Website', learn: 'Combine skills', summary: 'Build project', status: 'locked', xp: 0, coins: 0}
];

let firebaseData = {
 xp: 120,
 coins: 30,
 completed: 2,
 progress: { javascript: 2 },
 profile: { name: "Prince", level: "Intermediate" }
};

// Destructure user data
let { xp, coins, completed, progress, profile } = firebaseData;
console.log(`=== CODE ACADEMY DASHBOARD ===`);
console.log(`User: ${profile.name} - ${profile.level} - XP: ${xp}, Coins: ${coins}, Completed: ${completed}`);
console.log(`JS Progress: ${progress?.javascript?? 0} / ${TOTAL_LESSONS}`);

// Function to get status - uses object property
function getStatus(lessonId, completed) {
 if (lessonId <= completed) return "completed";
 if (lessonId === completed + 1) return "current";
 return "locked";
}

// Render with forEach and object access
console.log("\n--- Rendering Lessons (forEach + object access) ---");
lessons.forEach(lesson => {
 let status = getStatus(lesson.id, completed);
 let icon = status === 'completed'? '✅' : status === 'current'? '▶' : '🔒';
 console.log(`${icon} ${lesson.id}. ${lesson.title} - ${status.toUpperCase()} - ${lesson.xp} XP`);
});

// Array methods
console.log("\n--- Array Methods ---");
let titles = lessons.map(l => l.title);
console.log(`All titles (map): ${titles.slice(0, 3).join(', ')}... (${titles.length} total)`);

let completedLessons = lessons.filter(l => l.status === 'completed');
console.log(`Completed (filter): ${completedLessons.map(l => l.title).join(', ')}`);

let currentLesson = lessons.find(l => l.status === 'current');
console.log(`Current (find): ${currentLesson.title}`);

let totalXP = lessons.reduce((total, l) => total + l.xp, 0);
console.log(`Total XP earned (reduce): ${totalXP}`);

let hasLocked = lessons.some(l => l.status === 'locked');
console.log(`Has locked? (some): ${hasLocked}`);

let allHaveXP = lessons.every(l => typeof l.xp === 'number');
console.log(`All have XP number? (every): ${allHaveXP}`);

// Count by status with reduce
let countByStatus = lessons.reduce((counts, lesson) => {
 let status = getStatus(lesson.id, completed);
 counts[status] = (counts[status] || 0) + 1;
 return counts;
}, {});
console.log(`Count by status (reduce):`, countByStatus); // {completed:2, current:1, locked:7}

// Progress with filter
let completedCount = lessons.filter(l => l.id <= completed).length;
let percent = Math.round((completedCount / TOTAL_LESSONS) * 100);
console.log(`\nProgress (filter): ${completedCount}/${TOTAL_LESSONS} = ${percent}%`);

// Spread and destructuring
console.log("\n--- Spread and Destructuring ---");
let [firstLesson, secondLesson,...rest] = lessons;
console.log(`First: ${firstLesson.title}, Second: ${secondLesson.title}, Rest: ${rest.length} lessons`);

let updatedLessons = lessons.map(lesson => {
 if (lesson.id === 3) {
 return {...lesson, status: 'completed', xp: 100 }; // Spread + overwrite
 }
 return lesson;
});
console.log(`After completing lesson 3:`);
console.log(` Original status: ${lessons[2].status}, XP: ${lessons[2].xp} - unchanged`);
console.log(` Updated status: ${updatedLessons[2].status}, XP: ${updatedLessons[2].xp} - new array`);
console.log(` New total XP: ${updatedLessons.reduce((t, l) => t + l.xp, 0)}`);

// Optional chaining and nullish
console.log("\n--- Optional Chaining and Nullish ---");
let COURSE_ID = "javascript";
let jsProgress = firebaseData.progress?.[COURSE_ID]?? 0;
console.log(`JS progress via progress?.[COURSE_ID]?? 0: ${jsProgress}`);

let user2 = {};
console.log(`No progress: ${user2.progress?.javascript?? 0} (fallback 0)`);

// Complete lesson with spread immutable update
function completeLesson(lessonId) {
 console.log(`\n--- Completing Lesson ${lessonId} ---`);
 let status = getStatus(lessonId, completed);
 if (status === 'locked') {
 console.log(`🔒 Locked! Need ${completed + 1} first`);
 return lessons;
 }
 if (status === 'completed') {
 console.log(`✅ Already completed`);
 return lessons;
 }

 // Update lessons array immutably with map + spread
 let newLessons = lessons.map(l => {
 if (l.id === lessonId) {
 return {...l, status: 'completed', xp: 100, coins: 10 };
 }
 if (l.id === lessonId + 1) {
 return {...l, status: 'current' };
 }
 return l;
 });

 // Update user object immutably with spread
 let newUser = {...firebaseData, xp: firebaseData.xp + 100, coins: firebaseData.coins + 10, completed: firebaseData.completed + 1 };

 console.log(`🎉 Completed! New XP: ${newUser.xp}, Coins: ${newUser.coins}, Completed: ${newUser.completed}`);
 return { lessons: newLessons, user: newUser };
}

let result = completeLesson(3);
if (result.lessons) {
 lessons = result.lessons;
 firebaseData = result.user;
 ({ xp, coins, completed } = firebaseData); // Destructure updated
 console.log(`\nUpdated state: XP=${xp}, Completed=${completed}`);
 let newPercent = Math.round((completed / TOTAL_LESSONS) * 100);
 console.log(`New progress: ${completed}/${TOTAL_LESSONS} = ${newPercent}%`);
}

console.log("\n=== FINAL ===");
console.log(`Lessons: ${lessons.length}, XP: ${xp}, Coins: ${coins}, Completed: ${completed}`);
console.log(`Methods used: map (titles), filter (completed), find (current), reduce (total XP, count), some (has locked), every (all have XP), destructuring, spread (immutable),?. optional chaining,?? nullish`);
